
.card {
  width: 100%;
  max-width: 520px;
  margin: 0 auto;
  background: var(--c-surface);
  border: 1px solid var(--c-border);
  border-radius: 16px;
  overflow: hidden;
  font-family: var(--font-main);
  color: var(--c-text);
  font-size: 12px;
  box-shadow: 0 4px 16px rgba(169, 124, 134, 0.10);
}

.header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  padding: 14px 16px;
  background: linear-gradient(135deg, #fdf3f4, #f7e4e7);
  border-bottom: 1px solid var(--c-border);
}

.title-wrap {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.title {
  font-size: 17px;
  font-weight: 700;
  color: var(--c-primary-deep);
  letter-spacing: 4px;
}

.subtitle {
  font-size: 10px;
  color: var(--c-text-muted);
  letter-spacing: 1px;
}

.status {
  font-size: 11px;
  color: var(--c-primary-deep);
  background: #fff;
  border: 1px solid var(--c-border);
  border-radius: 999px;
  padding: 3px 10px;
}

.body {
  padding: 12px 14px 14px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.block {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.block-title {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  font-weight: 600;
  color: var(--c-primary-deep);
  letter-spacing: 1px;
}

.block-title i {
  color: var(--c-primary);
}

.bar-row {
  display: flex;
  align-items: center;
  gap: 8px;
}

.bar-label {
  width: 28px;
  font-size: 10px;
  color: var(--c-text-muted);
  flex-shrink: 0;
}

.track {
  flex: 1;
  height: 10px;
  border-radius: 999px;
  background: #f2e9df;
  overflow: hidden;
}

.fill {
  height: 100%;
  border-radius: 999px;
  transition: width 0.6s cubic-bezier(0.22, 1, 0.36, 1);
}

.fill-danger {
  background: linear-gradient(90deg, #eec3c3, var(--c-danger));
}

.fill-accent {
  background: linear-gradient(90deg, #c4ddd0, var(--c-accent));
}

.bar-pct {
  width: 28px;
  text-align: right;
  font-size: 10px;
  font-weight: 600;
  color: var(--c-text-muted);
  flex-shrink: 0;
}

.note {
  font-size: 10px;
  color: var(--c-text-muted);
  padding-left: 36px;
}

.chips {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.chip {
  background: #fbf4ec;
  border: 1px solid var(--c-border);
  border-radius: 999px;
  padding: 4px 10px;
  font-size: 11px;
  color: var(--c-text);
}

.marks {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.mark {
  background: #fdf5f5;
  border: 1px solid #f0d8d8;
  border-radius: 8px;
  padding: 4px 9px;
  font-size: 11px;
  color: #a06a6a;
}

.mark.empty {
  background: #f7f7f7;
  border-color: var(--c-border);
  color: var(--c-text-muted);
}

.events {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.event {
  font-size: 11px;
  color: var(--c-text);
  line-height: 1.6;
  padding-left: 8px;
  border-left: 2px solid var(--c-border);
}

.event.empty {
  color: var(--c-text-muted);
  border-left-color: #eee;
}
